//! Two-stage page-table lookup for Unicode scalar properties.
//!
//! `data.bin` is generated by `tools/unicode/properties/generate_data.py`.
//! Each scalar maps to one packed `u64`: five `General_Category` bits plus one
//! bit per binary property. The 256-scalar pages are deduplicated, so a lookup
//! is one index load and one payload load instead of a binary search.

const std = @import("std");

const data = @embedFile("data.bin");

/// Exact Unicode 17.0 `General_Category` values.
///
/// Declaration order is part of the generated binary format. The generator
/// records a fingerprint of this enum in the blob header so reordering it
/// without regenerating the data fails at compile time.
pub const Category = enum(u5) {
    Lu,
    Ll,
    Lt,
    Lm,
    Lo,
    Mn,
    Mc,
    Me,
    Nd,
    Nl,
    No,
    Pc,
    Pd,
    Ps,
    Pe,
    Pi,
    Pf,
    Po,
    Sm,
    Sc,
    Sk,
    So,
    Zs,
    Zl,
    Zp,
    Cc,
    Cf,
    Cs,
    Co,
    Cn,
};

pub const all_category_mask: u32 = 0x3fff_ffff;

const header_len = 16;
const index_count = readU16(8);
const page_count = readU16(10);
const index_offset = header_len;
const pages_offset = index_offset + @as(usize, index_count) * 2;

const default_value: u64 = @intFromEnum(Category.Cn);

comptime {
    if (data.len < header_len or !std.mem.eql(u8, data[0..4], "CJP2") or
        data[4] != 2 or data[5] != 17 or data[6] != 0 or data[7] != 0)
    {
        @compileError("invalid Unicode property data");
    }
    if (index_count != 0x1100 or
        pages_offset + @as(usize, page_count) * 256 * 8 != data.len)
    {
        @compileError("invalid Unicode property data lengths");
    }
    if (readU32(12) != categoryFingerprint()) {
        @compileError(
            "Unicode property data was generated for a different Category enum",
        );
    }
}

const ascii_values = buildAsciiValues();

fn buildAsciiValues() [128]u64 {
    @setEvalBranchQuota(10_000);
    var values: [128]u64 = undefined;
    var codepoint: u21 = 0;
    while (codepoint < 128) : (codepoint += 1) {
        values[codepoint] = rawValue(codepoint);
    }
    return values;
}

inline fn rawValue(codepoint: u21) u64 {
    const page = @as(usize, codepoint) >> 8;
    const slot = readU16(index_offset + page * 2);
    return readU64(
        pages_offset + (@as(usize, slot) * 256 +
            (@as(usize, codepoint) & 0xff)) * 8,
    );
}

/// Return the packed property word for one scalar value.
///
/// ASCII is served from a compile-time materialized first page; values above
/// the Unicode range resolve to `Cn` with every binary flag cleared.
pub inline fn value(codepoint: u21) u64 {
    if (codepoint < 0x80) return ascii_values[codepoint];
    if (codepoint > 0x10ffff) return default_value;
    return rawValue(codepoint);
}

/// Test one binary-property bit in the packed property word.
pub inline fn has(codepoint: u21, bit_index: u6) bool {
    return (value(codepoint) & (@as(u64, 1) << bit_index)) != 0;
}

pub inline fn category(codepoint: u21) Category {
    return @enumFromInt(@as(u5, @truncate(value(codepoint))));
}

pub fn categoryMask(category_value: Category) u32 {
    return @as(u32, 1) << @intFromEnum(category_value);
}

pub inline fn matchesMask(codepoint: u21, mask: u32) bool {
    return (categoryMask(category(codepoint)) & mask) != 0;
}

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, data[offset..][0..2], .little);
}

fn readU32(offset: usize) u32 {
    return std.mem.readInt(u32, data[offset..][0..4], .little);
}

fn readU64(offset: usize) u64 {
    return std.mem.readInt(u64, data[offset..][0..8], .little);
}

fn categoryFingerprint() u32 {
    @setEvalBranchQuota(10_000);
    var hash: u32 = 2166136261;
    inline for (@typeInfo(Category).@"enum".fields) |field| {
        for (field.name) |byte| {
            hash = (hash ^ byte) *% 16777619;
        }
        hash = (hash ^ 0xff) *% 16777619;
    }
    return hash;
}
